bool valid(long long k, long long a, long long b, long long c) {
    while (a > 0 || b > 0 || c > 0) {
        long long da = a % k;
        long long db = b % k;
        long long dc = c % k;

        if ((da + db) % k != dc) return false;

        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

